 inspect:{stage:1,number:'02',label:'INSPECT & RECORD',action:'A technician checks the equipment and records its condition and findings.',event:'Inspection findings saved',owner:'Inspection technician',result:'Condition recorded',caption:'Check the item → save the evidence → decide the next step',chip:'INSPECTED',status:'Inspection recorded',sub:'Condition and findings captured.'},
 hold:{stage:1,number:'!',label:'EXCEPTION · ITEM ON HOLD',action:'A serial number mismatch is found. The item stops here until someone resolves the issue.',event:'Serial number mismatch',owner:'Assigned exception owner',result:'Progression blocked',caption:'The item stays at Inspection. It cannot move to Disposition.',chip:'BLOCKED',status:'Return is on hold',sub:'An unresolved exception blocks progression.'},
