 handoff:{stage:3,number:'04',label:'HAND OFF & CLOSE',action:'The approved resale item completes a simulated inventory handoff. Its traveler closes with history intact.',event:'Simulated acknowledgment received',owner:'Inventory coordinator',result:'Traveler closed',caption:'Approved resale → simulated inventory update → recorded closure',chip:'COMPLETED',status:'Handoff acknowledged',sub:'Simulated inventory update complete.'}
