const controls=document.createElement('div');controls.className='scenario-controls';controls.innerHTML=`<div class="scenario-picker" role="group" aria-label="Choose the illustrated return scenario"><button class="selected" data-scenario="normal" aria-pressed="true">✓ Normal return</button><button data-scenario="exception" aria-pressed="false">⚑ Show a blocked return</button></div><div class="frame-controls"><button id="journey-prev" aria-label="Previous scene">←</button><span id="scene-counter">Scene 1 of 4</span><button id="journey-next" aria-label="Next scene">→</button><button id="journey-replay">↻ Replay</button></div>`;
