const caption=document.createElement('p');caption.className='visual-caption';caption.id='visual-caption';document.querySelector('.diagram-wrap').append(caption);
function showFrame(index){
 const sequence=sequences[scenario];frame=(index+sequence.length)%sequence.length;const key=sequence[frame],scene=scenes[key];current=scene.stage;const s=journey[current];
 document.querySelector('.process-surface').dataset.scene=key;
 document.querySelectorAll('[data-stage]').forEach(b=>{const active=Number(b.dataset.stage)===current;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});
 document.querySelectorAll('.process-node').forEach((n,i)=>{n.classList.toggle('active',i===current);n.classList.toggle('complete',i<current||key==='handoff')});
 document.querySelector('#moving-equipment').style.transform=`translateX(${current*265}px)`;
 document.querySelector('#step-label').textContent=key==='hold'||key==='resolve'?scene.label:s.label;
 document.querySelector('#step-title').textContent=key==='hold'?'An issue stops the item, not its history.':key==='resolve'?'Resolve the issue. Release the hold.':s.title;
 document.querySelector('#step-description').textContent=key==='hold'||key==='resolve'?scene.action:s.description;
 document.querySelector('#step-outcome').textContent='OUTPUT: '+(key==='hold'||key==='resolve'?scene.result:s.outcome);
 document.querySelector('#hero-status').textContent=scene.status;document.querySelector('#hero-sub').textContent=scene.sub;document.querySelector('#hero-count').textContent='0'+(current+1)+' / 04';document.querySelectorAll('.traveler-rail i').forEach((n,i)=>n.classList.toggle('on',i<=current));
 for(const [id,value] of Object.entries({'story-symbol':scene.number,'story-label':scene.label,'story-action':scene.action,'story-owner':scene.owner,'story-result':scene.result,'visual-caption':scene.caption,'item-chip':scene.chip,'scene-counter':`Scene ${frame+1} of ${sequence.length}`}))document.getElementById(id).textContent=value;
 document.querySelector('#hold-label').textContent=key==='hold'?'ON HOLD · Serial number mismatch':key==='resolve'?'RESOLVED · Evidence + note recorded':'Exception? Assign, review, and resolve.';
 document.querySelectorAll('[data-scenario]').forEach(b=>{const active=b.dataset.scenario===scenario;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});
 document.querySelector('#journey-prev').disabled=frame===0;
 document.querySelector('#journey-next').disabled=frame===sequence.length-1;
}
function showStage(index){showFrame(sequences[scenario].findIndex(key=>scenes[key].stage===index))}
function syncPlayback(){clearInterval(timer);const b=document.querySelector('#animation-toggle');b.textContent=playing?'Ⅱ Pause animation':'▷ Play animation';b.setAttribute('aria-pressed',String(playing));document.querySelector('.process-surface').classList.toggle('animation-paused',!playing||document.hidden);if(playing&&!document.hidden)timer=setInterval(()=>showFrame(frame+1),6500)}
function manualFrame(index){playing=false;syncPlayback();showFrame(index)}
document.querySelectorAll('[data-stage]').forEach(b=>b.addEventListener('click',()=>{playing=false;syncPlayback();showStage(Number(b.dataset.stage))}));
document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{scenario=b.dataset.scenario;showFrame(0);syncPlayback()});
document.querySelector('#animation-toggle').onclick=()=>{playing=!playing;syncPlayback()};document.querySelector('#journey-prev').onclick=()=>manualFrame(frame-1);document.querySelector('#journey-next').onclick=()=>manualFrame(frame+1);document.querySelector('#journey-replay').onclick=()=>{showFrame(0);playing=!window.matchMedia('(prefers-reduced-motion: reduce)').matches;syncPlayback()};document.addEventListener('visibilitychange',syncPlayback);showFrame(0);syncPlayback();
